<?php require_once __DIR__ . '/includes/config.php';role(['admin','payroll','auditor']);$p=db();$rows=$p->query('SELECT p.id,p.employee_no,p.employee_id,e.id AS found_id,e.employment_status FROM payroll p LEFT JOIN employees e ON e.employee_no=p.employee_no')->fetchAll();$n=0;foreach($rows as $r){$why='';if(!$r['found_id'])$why='Payroll employee number is missing from employee register';elseif($r['employment_status']!=='active')$why='Employee status is '.$r['employment_status'];if($why){$s=$p->prepare('INSERT IGNORE INTO investigations(payroll_id,employee_id,reason) VALUES(?,?,?)');$s->execute([$r['id'],$r['found_id'],$why]);$n+=$s->rowCount();}}log_action('RUN_DETECTION',"$n new flags");$_SESSION['flash']="Detection finished: $n new flags added for human review.";header('Location:investigations.php');